    @EventHandler( payloadType=CreatePublisherEvent.class )
    public void handle( CreatePublisherEvent event) {
	    LOGGER.info("handling CreatePublisherEvent - " + event );
	    Publisher entity = new Publisher();
            entity.setPublisherId( event.getPublisherId() );
            entity.setName( event.getName() );
            entity.setWebsite( event.getWebsite() );
            entity.setPublisherType( event.getPublisherType() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllPublisher( entity );
    }

    /*
     * @param	event UpdatePublisherEvent
     */
    @EventHandler( payloadType=UpdatePublisherEvent.class )
    public void handle( UpdatePublisherEvent event) {
    	LOGGER.info("handling UpdatePublisherEvent - " + event );
    	
	    Publisher entity = new Publisher();
            entity.setPublisherId( event.getPublisherId() );
            entity.setName( event.getName() );
            entity.setWebsite( event.getWebsite() );
            entity.setInventorySources( event.getInventorySources() );
            entity.setDeals( event.getDeals() );
            entity.setCreativeApprovals( event.getCreativeApprovals() );
            entity.setInsertionOrders( event.getInsertionOrders() );
            entity.setRateCards( event.getRateCards() );
            entity.setPublisherType( event.getPublisherType() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindPublisher( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllPublisher( entity );        
    }
    
