    /**
     * Method to retrieve the Publisher via an PublisherPrimaryKey.
     * @param 	id Long
     * @return 	Publisher
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Publisher handle( FindPublisherQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getPublisherId() );
    }
    
    /**
     * Method to retrieve a collection of all Publishers
     *
     * @param	query	FindAllPublisherQuery 
     * @return 	List<Publisher> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Publisher> handle( FindAllPublisherQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindPublisher,
 * but only if the id matches
 *
 * @param		entity	Publisher
 */
	protected void emitFindPublisher( Publisher entity ) {
		LOGGER.info("handling emitFindPublisher" );
		
	    queryUpdateEmitter.emit(FindPublisherQuery.class,
	                            query -> query.getFilter().getPublisherId().equals(entity.getPublisherId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllPublisher
	 * 
	 * @param		entity	Publisher
	 */
	protected void emitFindAllPublisher( Publisher entity ) {
		LOGGER.info("handling emitFindAllPublisher" );
		
	    queryUpdateEmitter.emit(FindAllPublisherQuery.class,
	                            query -> true,
	                            entity);
	}

